BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path=public,extensions,pg_temp;
SELECT plan(17);
SELECT has_table('public','mail_outbox','sealed outbox exists');
SELECT has_table('public','mail_attempts','delivery history exists');
SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('public.mail_outbox'::regclass,'public.mail_attempts'::regclass)),'both tables enable RLS');
SELECT ok(NOT has_table_privilege('anon','public.mail_outbox','SELECT'),'anonymous cannot read delivery metadata');
SELECT ok(NOT has_column_privilege('authenticated','public.mail_outbox','content_ciphertext','SELECT'),'members cannot read encrypted capabilities');
SELECT ok(NOT has_table_privilege('documentary_backend','public.mail_outbox','INSERT,UPDATE,DELETE'),'documentary role cannot write outbox');
SELECT ok(has_table_privilege('service_role','public.mail_outbox','INSERT,UPDATE'),'trusted delivery writer has required grants');
SELECT has_trigger('public','mail_outbox','mail_authority_immutable','mail authority cannot change');
SELECT has_trigger('public','mail_attempts','mail_attempt_immutable','history cannot change');
INSERT INTO public.tenancy_organizations(id,name,tax_id) VALUES('19800000-0000-4000-8000-000000000001','P25 pgTAP','P25-198');
SELECT is((SELECT document_attribution FROM public.tenancy_organizations WHERE id='19800000-0000-4000-8000-000000000001'),false,'customer documents hide attribution by default');
SELECT is((SELECT portal_attribution FROM public.tenancy_organizations WHERE id='19800000-0000-4000-8000-000000000001'),true,'portal attribution is configurable and initially visible');
INSERT INTO public.mail_outbox(id,org_id,event_key,kind,recipient,subject,content_ciphertext,created_by) VALUES('19800000-0000-4000-8000-000000000002','19800000-0000-4000-8000-000000000001','p25-test','APPROVAL','test@example.invalid','Sellado','ciphertext','19800000-0000-4000-8000-000000000003');
SELECT throws_ok($$UPDATE public.mail_outbox SET content_ciphertext='changed' WHERE event_key='p25-test'$$,'P0001','sealed_mail_immutable','content stays sealed');
SELECT throws_ok($$UPDATE public.mail_outbox SET recipient='other@example.invalid' WHERE event_key='p25-test'$$,'P0001','sealed_mail_immutable','recipient stays sealed');
SELECT throws_ok($$UPDATE public.mail_outbox SET id='19800000-0000-4000-8000-000000000009' WHERE event_key='p25-test'$$,'P0001','sealed_mail_immutable','capability-bound identity stays sealed');
SELECT throws_ok($$DELETE FROM public.mail_outbox WHERE event_key='p25-test'$$,'P0001','sealed_mail_immutable','authority cannot be deleted');
INSERT INTO public.tenancy_organizations(id,name,tax_id) VALUES('19800000-0000-4000-8000-000000000004','P25 other','P25-198-B');
SELECT throws_ok($$INSERT INTO public.mail_attempts(org_id,mail_id,attempt,event) VALUES('19800000-0000-4000-8000-000000000004','19800000-0000-4000-8000-000000000002',1,'SENT')$$,'P0001','mail_attempt_scope_mismatch','attempt cannot belong to another tenant');
INSERT INTO public.mail_attempts(org_id,mail_id,attempt,event) VALUES('19800000-0000-4000-8000-000000000001','19800000-0000-4000-8000-000000000002',1,'DISPATCHING');
SELECT throws_ok($$UPDATE public.mail_attempts SET event='SENT' WHERE mail_id='19800000-0000-4000-8000-000000000002'$$,'P0001','mail_attempt_immutable','delivery history cannot be rewritten');
SELECT * FROM finish();
ROLLBACK;
